// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Draft history"
// Changes: Store tests for a draft's own history: named snapshots, restore into the draft with a safety snapshot
//          first (last 10 kept), never touching the project; ended drafts refuse.

import { beforeEach, describe, expect, it } from 'vitest'
import { defaultProjectData, type ProjectData } from '#/lib/project'
import { openDatabase } from './db.server'
import { createProjectStore, type ProjectStore } from './projects.server'

const MINUTE = 60_000

let time: number
let store: ProjectStore
const advance = (ms: number) => {
  time += ms
}

beforeEach(() => {
  time = Date.parse('2026-01-01T10:00:00.000Z')
  store = createProjectStore(openDatabase(':memory:'), { now: () => new Date(time) })
})

const withGrammar = (grammar: string): ProjectData => ({ ...defaultProjectData(), ll: { grammar, input: '' } })

function openDraft() {
  const project = store.createProject('Výrazy', withGrammar('E -> id'))
  const draft = store.createDraft(project.id, 'Návrh', 'agent')!
  return { project, draft }
}

describe('named snapshots of a draft', () => {
  it("the human saves a named snapshot of a draft's current parts, in the draft's history only", () => {
    const { project, draft } = openDraft()
    store.editDraft(draft.id, { grammarRules: 'E -> x' }, { author: 'agent' })
    advance(MINUTE)

    const result = store.createDraftSnapshot(draft.id, '  Pred zmenou  ')
    expect(result).toMatchObject({ status: 'saved', snapshot: { label: 'Pred zmenou', kind: 'named', createdAt: '2026-01-01T10:01:00.000Z' } })
    const snapshot = result.status === 'saved' ? result.snapshot : null
    expect(store.listDraftSnapshots(draft.id)[0]).toEqual(snapshot)
    expect(store.getSnapshot(snapshot!.id)).toMatchObject({ draftId: draft.id, data: { ll: { grammar: 'E -> x' } } })
    expect(store.listSnapshots(project.id)).toEqual([])
    // Saving a snapshot is not a change of the draft.
    expect(store.getDraft(draft.id)!.revision).toBe(2)
  })

  it('named snapshots are never pruned', () => {
    const { draft } = openDraft()
    for (let i = 0; i < 40; i++) store.createDraftSnapshot(draft.id, `v${i}`)
    expect(store.listDraftSnapshots(draft.id).filter((s) => s.kind === 'named')).toHaveLength(40)
  })

  it('an ended or unknown draft gets no new snapshots', () => {
    const { draft } = openDraft()
    store.discardDraft(draft.id)
    expect(store.createDraftSnapshot(draft.id, 'Neskoro')).toMatchObject({ status: 'ended' })
    expect(store.createDraftSnapshot('nope', 'X')).toEqual({ status: 'missing' })
    expect(store.listDraftSnapshots(draft.id).map((s) => s.kind)).toEqual(['final'])
  })
})

describe('restoring a draft snapshot', () => {
  it('restores the snapshot into the draft after keeping its current state as a safety snapshot; the project is untouched', () => {
    const { project, draft } = openDraft()
    store.editDraft(draft.id, { grammarRules: 'E -> a', reductionRules: 'E -> a' }, { author: 'agent' })
    const saved = store.createDraftSnapshot(draft.id, 'Verzia A')
    store.editDraft(draft.id, { grammarRules: 'E -> b' }, { author: 'agent' })
    advance(MINUTE)

    const snapshotId = saved.status === 'saved' ? saved.snapshot.id : -1
    const result = store.restoreDraftSnapshot(draft.id, snapshotId)

    expect(result.status).toBe('saved')
    const restored = store.getDraft(draft.id)!
    expect(restored.parts.grammarRules).toBe('E -> a')
    expect(restored).toMatchObject({
      revision: 4,
      // Only the part that actually changed back gets the new part revision.
      partRevisions: { grammarRules: 4, reductionRules: 2, definition: 1, precTable: 1 },
      lastChangedBy: 'human',
      humanViewedRevision: 4,
      updatedAt: '2026-01-01T10:01:00.000Z',
    })
    const [safety] = store.listDraftSnapshots(draft.id)
    expect(safety).toMatchObject({ kind: 'safety', label: 'Pred obnovením „Verzia A“' })
    expect(store.getSnapshot(safety.id)!.data.ll.grammar).toBe('E -> b')
    expect(store.getProject(project.id)).toEqual(project)
    expect(store.listSnapshots(project.id)).toEqual([])
  })

  it("keeps the last 10 safety snapshots of a draft, without pruning the project's", () => {
    const { project, draft } = openDraft()
    store.restoreSnapshot(project.id, store.createSnapshot(project.id, 'P')!.id)
    const saved = store.createDraftSnapshot(draft.id, 'A')
    const snapshotId = saved.status === 'saved' ? saved.snapshot.id : -1
    for (let i = 0; i < 12; i++) store.restoreDraftSnapshot(draft.id, snapshotId)
    expect(store.listDraftSnapshots(draft.id).filter((s) => s.kind === 'safety')).toHaveLength(10)
    expect(store.listDraftSnapshots(draft.id).filter((s) => s.kind === 'named')).toHaveLength(1)
    expect(store.listSnapshots(project.id).filter((s) => s.kind === 'safety')).toHaveLength(1)
  })

  it("only the draft's own snapshots can be restored into it, and only while it is open", () => {
    const { project, draft } = openDraft()
    const other = store.createDraft(project.id, 'Iný', 'agent')!
    const projectSnapshot = store.createSnapshot(project.id, 'Projekt')!
    const foreign = store.createDraftSnapshot(other.id, 'Cudzí')
    const own = store.createDraftSnapshot(draft.id, 'Vlastný')

    expect(store.restoreDraftSnapshot(draft.id, projectSnapshot.id)).toEqual({ status: 'missing' })
    expect(store.restoreDraftSnapshot(draft.id, foreign.status === 'saved' ? foreign.snapshot.id : -1)).toEqual({ status: 'missing' })
    expect(store.restoreDraftSnapshot('nope', 1)).toEqual({ status: 'missing' })
    store.discardDraft(draft.id)
    expect(store.restoreDraftSnapshot(draft.id, own.status === 'saved' ? own.snapshot.id : -1)).toMatchObject({ status: 'ended' })
    expect(store.listDraftSnapshots(draft.id).map((s) => s.kind)).toEqual(['final', 'named'])
  })
})
